TASK_RE = re.compile(r"^/tasks/(\d+)$")


class Handler(BaseHTTPRequestHandler):
    server_version = "TaskForge/1.0"
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        # Silence per-request log output.
        return

    def _send_json(self, status, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _read_body(self):
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except (TypeError, ValueError):
            length = 0
        return self.rfile.read(length)

    def _parse_json(self, raw):
        if not raw:
            return None, None
        try:
            return json.loads(raw), None
        except (ValueError, json.JSONDecodeError):
            return None, "invalid json"

    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path == "/":
            self._serve_ui()
        elif parsed.path == "/tasks":
            self._list_tasks(parsed.query)
        else:
            self._send_json(404, {"error": "not found"})

    def do_POST(self):
        parsed = urlparse(self.path)
        if parsed.path != "/tasks":
            self._send_json(404, {"error": "not found"})
            return
        raw = self._read_body()
        data, err = self._parse_json(raw)
        if err or not isinstance(data, dict):
            self._send_json(400, {"error": "invalid json"})
            return
        title = data.get("title")
        if not isinstance(title, str) or title.strip() == "":
            self._send_json(400, {"error": "title must be a non-blank string"})
            return
        key = self.headers.get("Idempotency-Key")
        conn = db.connect(self.server.db_path)
        try:
            conn.execute("BEGIN IMMEDIATE")
            task, _created = db.find_or_create_task(conn, title, key)
            conn.execute("COMMIT")
        except Exception:
            try:
                conn.execute("ROLLBACK")
            except Exception:
                pass
            conn.close()
            self._send_json(500, {"error": "server error"})
            return
        conn.close()
        self._send_json(201, task)

    def do_PATCH(self):
        parsed = urlparse(self.path)
        m = TASK_RE.match(parsed.path)
        if not m:
            self._send_json(404, {"error": "not found"})
            return
        task_id = int(m.group(1))
        raw = self._read_body()
        data, err = self._parse_json(raw)
        if (
            err
            or not isinstance(data, dict)
            or "done" not in data
            or not isinstance(data["done"], bool)
        ):
            self._send_json(400, {"error": "request body must be JSON with a boolean 'done'"})
            return

